-- Name: reject_cold_partition_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_cold_partition_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                RAISE EXCEPTION
                    'Partition % is in the read-only cold archive tier', TG_TABLE_NAME
                    USING ERRCODE = '55000';
            END
            $$;


