--
-- Name: tokens; Type: TABLE; Schema: mcp_private; Owner: -
--

CREATE TABLE mcp_private.tokens (
    id bigint NOT NULL,
    user_id integer NOT NULL,
    token_hash text NOT NULL,
    label text NOT NULL,
    profile text NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tokens_profile_check CHECK ((profile = ANY (ARRAY['products'::text, 'design'::text, 'finance'::text, 'merchandise'::text, 'operation'::text, 'development'::text, 'customer_service'::text])))
);


