--
-- Name: identities; Type: VIEW; Schema: mcp_private; Owner: -
--

CREATE VIEW mcp_private.identities WITH (security_barrier='true') AS
 SELECT token.id AS token_id,
    token.user_id,
    token.token_hash,
    token.profile,
    token.expires_at,
    token.revoked_at,
    users.status,
    users.department_code,
    users.role_code,
    roles.permissions
   FROM ((mcp_private.tokens token
     JOIN public.auth_users users ON ((users.id = token.user_id)))
     JOIN public.auth_roles roles ON ((roles.code = users.role_code)));


