CREATE TABLE public.product_copywriting (
    id bigint NOT NULL,
    brand text NOT NULL,
    source_product_id bigint NOT NULL,
    sku text NOT NULL,
    launch_date date NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    content text,
    source_facts json NOT NULL,
    source_hash text NOT NULL,
    source_updated_at text NOT NULL,
    provider text NOT NULL,
    model text NOT NULL,
    endpoint text NOT NULL,
    template_version text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    claim_token text,
    lease_expires_at timestamp with time zone,
    last_error text,
    error_status integer,
    generated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    input_prompt text,
    system_prompt text,
    previous_result json,
    input_image json,
    CONSTRAINT ck_product_copywriting_completed CHECK (((status <> 'completed'::text) OR ((content IS NOT NULL) AND (length(content) > 0) AND (generated_at IS NOT NULL)))),
    CONSTRAINT ck_product_copywriting_status CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: copywriting; Type: VIEW; Schema: mcp_readonly; Owner: -
--

CREATE VIEW mcp_readonly.copywriting WITH (security_barrier='true') AS
 SELECT saved.brand,
    saved.source_product_id AS product_id,
    saved.sku,
    saved.status,
    saved.content,
    saved.input_prompt,
    saved.model,
    saved.generated_at
   FROM (public.product_copywriting saved
     JOIN mcp_readonly.products product ON (((product.brand = saved.brand) AND (product.id = saved.source_product_id))));


--
-- Name: product_copywriting_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_copywriting_history (
    id bigint NOT NULL,
    brand text NOT NULL,
    source_product_id bigint NOT NULL,
    snapshot_key text NOT NULL,
    generated_at timestamp with time zone NOT NULL,
    model text NOT NULL,
    sku text NOT NULL,
    snapshot json NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: copywriting_history; Type: VIEW; Schema: mcp_readonly; Owner: -
--

CREATE VIEW mcp_readonly.copywriting_history WITH (security_barrier='true') AS
 SELECT history.id,
    history.brand,
    history.source_product_id AS product_id,
    history.sku,
    (history.snapshot ->> 'content'::text) AS content,
    (history.snapshot ->> 'input_prompt'::text) AS input_prompt,
    history.model,
    history.generated_at,
        CASE
            WHEN (((history.snapshot -> 'input_image'::text) ->> 'source'::text) = ANY (ARRAY['us3'::text, 'shared'::text, 'local'::text])) THEN ((history.snapshot -> 'input_image'::text) ->> 'source'::text)
            ELSE 'unknown'::text
        END AS image_source
   FROM (public.product_copywriting_history history
     JOIN mcp_readonly.products product ON (((product.brand = history.brand) AND (product.id = history.source_product_id))));


