--
-- Name: v_fine_table_snapshot_rows; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_fine_table_snapshot_rows AS
 SELECT batches.brand,
    batches.snapshot_date,
    refs.id,
    refs.batch_id,
    refs.sku,
    refs.original_sku,
    refs.row_index,
    ((payloads.payload || metrics.payload))::json AS payload,
    refs.created_at
   FROM (((public.fine_table_snapshot_refs_2024 refs
     JOIN public.fine_table_snapshot_batches batches ON ((batches.id = refs.batch_id)))
     JOIN public.fine_table_snapshot_payloads payloads ON ((payloads.id = refs.payload_id)))
     JOIN public.fine_table_snapshot_metrics metrics ON ((metrics.id = refs.metrics_id)))
  WHERE ((batches.snapshot_date >= '2024-01-01'::date) AND (batches.snapshot_date < '2025-01-01'::date))
UNION ALL
 SELECT batches.brand,
    batches.snapshot_date,
    refs.id,
    refs.batch_id,
    refs.sku,
    refs.original_sku,
    refs.row_index,
    ((payloads.payload || metrics.payload))::json AS payload,
    refs.created_at
   FROM (((public.fine_table_snapshot_refs_2025 refs
     JOIN public.fine_table_snapshot_batches batches ON ((batches.id = refs.batch_id)))
     JOIN public.fine_table_snapshot_payloads payloads ON ((payloads.id = refs.payload_id)))
     JOIN public.fine_table_snapshot_metrics metrics ON ((metrics.id = refs.metrics_id)))
  WHERE ((batches.snapshot_date >= '2025-01-01'::date) AND (batches.snapshot_date < '2026-01-01'::date))
UNION ALL
 SELECT batches.brand,
    batches.snapshot_date,
    refs.id,
    refs.batch_id,
    refs.sku,
    refs.original_sku,
    refs.row_index,
    ((payloads.payload || metrics.payload))::json AS payload,
    refs.created_at
   FROM (((public.fine_table_snapshot_refs_2026 refs
     JOIN public.fine_table_snapshot_batches batches ON ((batches.id = refs.batch_id)))
     JOIN public.fine_table_snapshot_payloads payloads ON ((payloads.id = refs.payload_id)))
     JOIN public.fine_table_snapshot_metrics metrics ON ((metrics.id = refs.metrics_id)))
  WHERE ((batches.snapshot_date >= '2026-01-01'::date) AND (batches.snapshot_date < '2027-01-01'::date));


