--
-- Name: v_jst_purchase_inbound_quantity_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_jst_purchase_inbound_quantity_daily AS
 SELECT inbound_date,
    style_color_code AS product_code,
    goods_name AS product_full_name,
    (inbound_quantity - return_excluded_quantity) AS inbound_quantity,
    (inbound_amount - return_excluded_amount) AS inbound_amount,
    ((source_line_count - return_excluded_rows))::bigint AS source_line_count,
    purchase_first_inbound_at AS first_inbound_at,
    purchase_last_inbound_at AS last_inbound_at
   FROM public.jst_purchase_inbound_daily
  WHERE (is_womens AND (status = ANY (ARRAY['已入库'::text, '已结算'::text])) AND (inbound_type = ANY (ARRAY['采购进仓'::text, '加工进仓'::text])) AND (return_excluded_rows IS NOT NULL) AND (source_line_count > return_excluded_rows) AND (style_color_code IS NOT NULL) AND (btrim(style_color_code) <> ''::text));


--
-- Name: v_jst_purchase_inbound_quantity_by_goods; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_jst_purchase_inbound_quantity_by_goods AS
 SELECT product_code,
    max(product_full_name) AS product_full_name,
    sum(inbound_quantity) AS inbound_quantity,
    sum(inbound_amount) AS inbound_amount,
    (sum(source_line_count))::bigint AS source_line_count,
    min(inbound_date) AS first_inbound_date,
    max(inbound_date) AS last_inbound_date
   FROM public.v_jst_purchase_inbound_quantity_daily
  GROUP BY product_code;


